<include file="Public:header"/>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>                    <a href="{pigcms{:U('User/levellist')}">等级管理</a>                    <a href="javascript:void(0);" onclick="window.o2oTop.artiframe('{pigcms{:U('User/addlevel')}','添加一个等级',650,500,true,false,false,addbtn,'add',true);" style="margin-left:20px;">添加等级</a>                    <if condition="$config.open_recharge_level eq 1">                        <a href="{pigcms{:U('User/recharge_level')}">充值获得等级</a>                    </if>                    <a href="{pigcms{:U('User/activation_code_list')}">激活码管理</a>                    <a href="{pigcms{:U('User/open_user_level_log')}" class="on">SYSTEM_USER_LEVEL_LOG_1</a>                </ul>			</div>			<table class="search_table" width="100%">				<tr>					<td>						<form action="{pigcms{:U('User/open_user_level_log')}" method="get">							<input type="hidden" name="c" value="User"/>							<input type="hidden" name="a" value="open_user_level_log"/>                            用户ID: <input type="text" name="uid" class="input-text" value="{pigcms{$_GET['uid']}"/>                            会员等级: <input type="text" name="level" class="input-text" value="{pigcms{$_GET['level']}"/>                            开通方式:                            <select name="open_type">                                <option value="" <if condition="$_GET['open_type'] eq ''">selected="selected"</if>>全部</option>                                <option value="-2" <if condition="$_GET['open_type'] eq '-2'">selected="selected"</if>>管理员开通</option>                                <option value="1" <if condition="$_GET['open_type'] eq '1'">selected="selected"</if>>用户{pigcms{$config['score_name']}开通</option>                                <option value="2" <if condition="$_GET['open_type'] eq '2'">selected="selected"</if>>用户余额开通</option>                                <option value="3" <if condition="$_GET['open_type'] eq '3'">selected="selected"</if>>激活码开通</option>                            </select>                            <font color="#000">开通日期筛选：</font>                            <input type="text" class="input-text" name="begin_time" style="width:120px;" id="d4311"  value="{pigcms{$_GET.begin_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="text" class="input-text" name="end_time" style="width:120px;" id="d4311" value="{pigcms{$_GET.end_time}" onfocus="WdatePicker({readOnly:true,dateFmt:'yyyy-MM-dd'})"/>                            <input type="submit" value="查询" class="button"/>                            <a href="javascript:void(0)" onclick="exports()" class="button" style="float:right;margin-right: 10px;">导出用户</a>						</form>					</td>				</tr>			</table>			<form name="myform" id="myform" action="" method="post">				<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup>							<col/>							<col/>							<col/>							<col/>							<col/>							<if condition="$config['level_balance']">								<col/>							</if>							<col width="180" align="center"/>						</colgroup>						<thead>							<tr>								<th width="50px">ID</th>                                <th >用户ID</th>                                <th >会员等级</th>                                <th >开通方式</th>                                <th >扣除{pigcms{$config['score_name']}</th>                                <th >扣除余额</th>                                <th >开通时间</th>                                <th >到期时间</th>                                <th >操作时间</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>                                        <td>{pigcms{$vo.log_id}</td>                                        <td>{pigcms{$vo.uid}</td>                                        <td>{pigcms{$vo.level}</td>                                        <td>{pigcms{$open_type_info[$vo['open_type']]}</td>                                        <td>                                            <php>if ($vo['score_used_count']>0){ echo $vo['score_used_count']; }else{echo '-';}</php>                                        </td>                                        <td>                                            <php>if ($vo['balance_pay']>0){ echo $vo['balance_pay']; }else{echo '-';}</php>                                        </td>                                        <td>                                            <php>if ($vo['open_time']>0) {</php>                                            {pigcms{$vo.open_time|date="Y-m-d H:i:s",###}                                            <php>}else{</php>                                            -                                            <php>}</php>                                        </td>                                        <td>                                            <php>if ($vo['end_time']>0) {</php>                                            {pigcms{$vo.end_time|date="Y-m-d H:i:s",###}                                            <php>}elseif ($vo.level>0){</php>                                            永久                                            <php>} else {</php>                                            -                                            <php>}</php>                                        </td>                                        <td>{pigcms{$vo.log_time|date="Y-m-d H:i:s",###}</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="9">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="9">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>			</form>		</div><script>    var url = "{pigcms{$config.site_url}";    var export_url = "{pigcms{:U('User/open_level_log_export')}";</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><include file="Public:footer"/>